#pragma once

#include <cstddef>
#include <cstdint>

// Pure text rendering, no ESP-IDF/hardware dependency -- mirrors
// eyes_geometry.h's separation so it's host-testable (see firmware-synora/tests/).
// The actual font data (font_noto_sans_vi.cc, generated by scripts/gen_font.py)
// is a separate, much larger GlyphBitmap table; this file only knows how to
// walk one.

// One glyph's bitmap and metrics. bitmap is nullptr for a zero-width glyph
// (e.g. space): advance-only, nothing blitted. Rows are 1bpp, MSB-first,
// each row padded to a whole byte (row_bytes = (width + 7) / 8).
struct GlyphBitmap {
    uint32_t codepoint;
    uint8_t width;
    uint8_t height;
    int8_t x_offset;   // pen-relative horizontal bearing
    int8_t y_offset;   // pen-relative vertical bearing (baseline-relative, + = down)
    uint8_t advance;   // horizontal pen advance after drawing this glyph
    const uint8_t* bitmap;
};

// Decodes utf8_text as UTF-8, looks up each codepoint in glyphs (MUST be
// sorted ascending by codepoint -- looked up via binary search) and blits
// set bits as `color` pixels into a fb_width x fb_height RGB565 framebuffer,
// pen starting at (x, y) (y is the text baseline). A codepoint missing from
// the table draws nothing but still advances the pen (by line_height / 2)
// rather than stopping -- a font gap should degrade gracefully, not corrupt
// layout for the rest of the string. Single-line only; callers wanting
// multiple lines call this once per line at their own y positions.
// Returns the total pixel width drawn (== MeasureTextWidth of the same call).
int DrawText(uint16_t* framebuffer, int fb_width, int fb_height, int x, int y, const char* utf8_text, uint16_t color,
             const GlyphBitmap* glyphs, size_t glyph_count, uint8_t line_height);

// Same UTF-8 decode + lookup + advance accumulation as DrawText, without
// touching the framebuffer -- for centering text before drawing it. Pass the
// same line_height as the matching DrawText call so missing-glyph fallback
// widths agree between the two.
int MeasureTextWidth(const char* utf8_text, const GlyphBitmap* glyphs, size_t glyph_count, uint8_t line_height);

// Greedily word-wraps utf8_text (split on ASCII spaces) to fit within
// fb_width - x, calling DrawText once per line starting at x, with y
// advancing by line_height per line. For content whose line breaks aren't
// known ahead of time (e.g. synora_display.cc's font-test dump) -- unlike
// the pairing/dashboard screens' fixed strings, which stay hand-wrapped at
// exact pixel positions since there are only two of them (see
// synora_display.cc's kPairingTitleLines comment). Stops drawing (but still
// returns) once a line's baseline would land at or past fb_height. Returns
// the y position just after the last line actually drawn.
int DrawWrappedText(uint16_t* framebuffer, int fb_width, int fb_height, int x, int y, const char* utf8_text,
                     uint16_t color, const GlyphBitmap* glyphs, size_t glyph_count, uint8_t line_height);
